    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
# Generate a random Pythagorean triple via Euclid's formula, then scale.
# Ensure nontrivial and that the resulting p+q is reasonably large.
for _ in range(200):
    m = rng.randint(3, 30)
    n = rng.randint(1, m-1)
    # coprime and opposite parity
    if math.gcd(m, n) != 1:
        continue
    if (m - n) % 2 == 0:
        continue
    k = rng.randint(2, 40)
    # two orientations for legs
    if rng.random() < 0.5:
        a = k * (m*m - n*n)
        b = k * (2*m*n)
    else:
        a = k * (2*m*n)
        b = k * (m*m - n*n)
    if a <= 0 or b <= 0 or a == b:
        continue
    # Compute c and r to ensure validity
    c = k * (m*m + n*n)
    r = (a + b - c) // 2
    if r <= 1:
        continue
    # Compute the reduced fraction for D^2 / r^2 to assess nontriviality
    # Formula: D^2 / r^2 = 8 + 8 * r^2 * (a - b)^2 / (a^2 b^2)
    A2 = a*a
    B2 = b*b
    R_num = 8 * A2 * B2 + 8 * (r*r) * ((a - b)*(a - b))
    R_den = A2 * B2
    g = math.gcd(R_num, R_den)
    p = R_num // g
    q = R_den // g
    # Nontriviality: avoid too small p+q
    if p + q < 50:
        continue
    return {'a_leg': a, 'b_leg': b}
# Fallback deterministic nontrivial instance (classic 3-4-5 scaled)
return {'a_leg': 120, 'b_leg': 90}

